T = {"fa": {}, "en": {}, "de": {}}
for _k, (_fa, _en, _de) in _S.items():
    T["fa"][_k], T["en"][_k], T["de"][_k] = _fa, _en, _de

def tr(_lang, _key, **kw):
    s = T.get(_lang, T["fa"])[_key]
    return s.format(**kw) if kw else s

